<?php $limitPrefix=$limitPrefix??''; ?><div class="fields call-fields">
<?php foreach(['max_file_mb'=>'حداکثر حجم هر فایل (مگابایت)','min_files'=>'حداقل تعداد فایل هر اثر'] as $key=>$label): ?><label><?= e($label) ?><input type="number" min="<?= $key==='min_files'?'0':'1' ?>" name="<?= e($limitPrefix.$key) ?>" value="<?= e($cfg[$key]??($key==='min_files'?1:20)) ?>" required></label><?php endforeach ?>
<?php foreach(['max_files'=>'حداکثر تعداد فایل هر اثر','max_batch_works'=>'حداکثر آثار در یک نوبت ارسال','max_user_works'=>'حداکثر مجموع آثار هر کاربر در فراخوان','max_total_mb'=>'سقف مجموع حجم فایل‌های یک ارسال (مگابایت)'] as $key=>$label):$v=$cfg[$key]??null; ?><fieldset class="call-limit"><legend><?= e($label) ?></legend><select name="<?= e($limitPrefix.$key) ?>[mode]" data-call-limit-mode><option value="unlimited" <?= $v===null?'selected':'' ?>><?= $key==='max_total_mb'?'بدون سقف اختصاصی؛ تابع فضای حساب':'بدون محدودیت تعداد' ?></option><option value="limited" <?= $v!==null?'selected':'' ?>><?= $key==='max_total_mb'?'سقف مشخص':'تعداد مشخص' ?></option></select><input type="number" min="1" name="<?= e($limitPrefix.$key) ?>[value]" value="<?= e($v??'') ?>" placeholder="مقدار" aria-label="<?= e($label) ?>" data-call-limit-value></fieldset><?php endforeach ?>
